## 3. Progressive Loading with Viewport Filtering

Load only visible data in chunks:

```javascript
// Divide your data into spatial chunks (grid cells)
const CHUNK_SIZE = 10000; // Points per chunk

map.on('load', () => {
  map.addSource('visible-gps', {
    type: 'geojson',
    data: { type: 'FeatureCollection', features: [] }
  });

  map.addLayer({
    id: 'gps-heatmap',
    type: 'heatmap',
    source: 'visible-gps',
    paint: {
      'heatmap-weight': 1,
      'heatmap-intensity': 2,
      'heatmap-color': [
        'interpolate', ['linear'], ['heatmap-density'],
        0, 'rgba(0,0,255,0)',
        0.1, 'rgba(0,0,255,0.5)',
        0.3, 'rgba(0,255,0,0.7)',
        0.5, 'rgba(255,255,0,0.8)',
        1, 'rgba(255,0,0,1)'
      ],
      'heatmap-radius': 15
    }
  });

  let loadTimeout;

  async function loadVisibleData() {
    clearTimeout(loadTimeout);
    loadTimeout = setTimeout(async () => {
      const bounds = map.getBounds();
      const zoom = map.getZoom();

      // Load appropriate density for zoom level
      const density = zoom > 10 ? 'high' : zoom > 6 ? 'medium' : 'low';

      try {
        const response = await fetch(
          `/api/gps-viewport?bbox=${bounds.toBBoxString()}&density=${density}&limit=${CHUNK_SIZE}`
        );
        const data = await response.json();

        map.getSource('visible-gps').setData(data);
      } catch (error) {
        console.error('Failed to load GPS data:', error);
      }
    }, 200); // Debounce
  }

  map.on('moveend', loadVisibleData);
  loadVisibleData();
});
```

