```javascript
import { SearchSession } from '@mapbox/search-js-core';

class CustomSearchBox {
  constructor(accessToken, options = {}) {
    // Search JS Core handles all the complexity
    this.search = new SearchSession({ accessToken });
    this.options = options;

    this.setupElements();
    this.bindEvents();
  }

  setupElements() {
    this.input = document.getElementById('search-input');
    this.dropdown = document.getElementById('search-dropdown');
    this.results = [];
    this.selectedIndex = -1;
  }

  bindEvents() {
    // Search JS Core handles debouncing automatically
    this.input.addEventListener('input', async (e) => {
      const query = e.target.value;

      if (query.length < 2) {
        this.hideDropdown();
        return;
      }

      await this.performSearch(query);
    });

    // Your custom keyboard navigation
    this.input.addEventListener('keydown', (e) => {
      this.handleKeydown(e);
    });

    // Hide dropdown when clicking outside
    document.addEventListener('click', (e) => {
      if (!this.input.contains(e.target) && !this.dropdown.contains(e.target)) {
        this.hideDropdown();
      }
    });
  }

  async performSearch(query) {
    try {
      // Search JS Core handles session tokens automatically
      const response = await this.search.suggest(query, {
        country: this.options.country,
        types: this.options.types,
        proximity: this.options.proximity,
        limit: 8
      });

      this.results = response.suggestions || [];
      this.renderDropdown();
    } catch (error) {
      console.error('Search error:', error);
      this.hideDropdown();
    }
  }

  renderDropdown() {
    if (this.results.length === 0) {
      this.dropdown.innerHTML = '<div class="no-results">No results found</div>';
      this.showDropdown();
      return;
    }

    // Your completely custom result rendering
    this.dropdown.innerHTML = this.results
      .map((result, index) => `
        <div class="search-result ${index === this.selectedIndex ? 'selected' : ''}" 
             data-index="${index}">
          <div class="result-icon">📍</div>
          <div class="result-content">
            <div class="result-name">${result.name}</div>
            <div class="result-address">${result.place_formatted || ''}</div>
            ${result.categories ? `<div class="result-category">${result.categories.join(', ')}</div>` : ''}
          </div>
          <div class="result-type">${this.getResultTypeIcon(result.feature_type)}</div>
        </div>
      `)
      .join('');

    // Add click handlers
    this.dropdown.querySelectorAll('.search-result').forEach((el, index) => {
      el.addEventListener('click', () => this.selectResult(index));
    });

    this.showDropdown();
  }

  // Your custom keyboard navigation
  handleKeydown(e) {
    if (!this.isDropdownVisible()) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        this.selectedIndex = Math.min(this.selectedIndex + 1, this.results.length - 1);
        this.updateSelection();
        break;

      case 'ArrowUp':
        e.preventDefault();
        this.selectedIndex = Math.max(this.selectedIndex - 1, -1);
        this.updateSelection();
        break;

      case 'Enter':
        e.preventDefault();
        if (this.selectedIndex >= 0) {
          this.selectResult(this.selectedIndex);
        }
        break;

      case 'Escape':
        this.hideDropdown();
        this.input.blur();
        break;
    }
  }

  updateSelection() {
    this.dropdown.querySelectorAll('.search-result').forEach((el, index) => {
      el.classList.toggle('selected', index === this.selectedIndex);
    });

    // Scroll selected item into view
    const selected = this.dropdown.querySelector('.selected');
    if (selected) {
      selected.scrollIntoView({ block: 'nearest' });
    }
  }

  async selectResult(index) {
    const suggestion = this.results[index];

    try {
      // Search JS Core handles session tokens automatically
      const result = await this.search.retrieve(suggestion);
      const feature = result.features[0];

      // Your custom selection handling
      this.onResultSelect(feature);

      this.input.value = feature.properties.name;
      this.hideDropdown();
    } catch (error) {
      console.error('Retrieve error:', error);
    }
  }

  onResultSelect(feature) {
    // Your custom logic here
    console.log('Selected:', feature);

    // Example: trigger custom event
    this.input.dispatchEvent(new CustomEvent('searchSelect', { 
      detail: feature 
    }));
  }

  getResultTypeIcon(type) {
    const icons = {
      'poi': '🏪',
      'address': '🏠', 
      'place': '📍',
      'postcode': '📮'
    };
    return icons[type] || '📍';
  }

  showDropdown() {
    this.dropdown.style.display = 'block';
    this.dropdown.classList.add('visible');
  }

  hideDropdown() {
    this.dropdown.style.display = 'none';
    this.dropdown.classList.remove('visible');
    this.selectedIndex = -1;
  }

  isDropdownVisible() {
    return this.dropdown.style.display === 'block';
  }
}

// Usage
const searchBox = new CustomSearchBox('YOUR_MAPBOX_TOKEN', {
  country: 'US',
  types: 'address,poi'
});

// Listen for selections
document.getElementById('search-input').addEventListener('searchSelect', (e) => {
  const feature = e.detail;
  const [lng, lat] = feature.geometry.coordinates;

  // Fly map to location, add marker, etc.
  map.flyTo({ center: [lng, lat], zoom: 15 });
});
```

