**Fix**: Use debounced search + Symbol layers
```javascript
import * as turf from '@turf/turf';

// Load all data once, filter in memory
let allStores = null;

// Debounced search (300ms delay)
const debouncedFilter = debounce(filterStores, 300);
document.getElementById('search-input').addEventListener('input', e => debouncedFilter(e.target.value));

function debounce(func, wait) {
  let timeout;
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout);
      func(...args);
    };
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

// Client-side filtering
function filterStores(searchTerm) {
  const filtered = {
    type: 'FeatureCollection',
    features: allStores.features.filter(store => {
      const name = store.properties.name.toLowerCase();
      const address = store.properties.address.toLowerCase();
      const search = searchTerm.toLowerCase();
      return name.includes(search) || address.includes(search);
    })
  };

  // Update existing source instead of removing/re-adding
  map.getSource('stores').setData(filtered);

  // Rebuild listing
  buildLocationList(filtered);
}
