```typescript
import { ChatOpenAI } from '@langchain/openai';
import { AgentExecutor, createToolCallingAgent } from 'langchain/agents';
import { DynamicStructuredTool } from '@langchain/core/tools';
import { ChatPromptTemplate, MessagesPlaceholder } from '@langchain/core/prompts';
import { z } from 'zod';

// MCP Server wrapper for hosted server
class MapboxMCP {
  private url = 'https://mcp.mapbox.com/mcp';
  private headers: Record<string, string>;

  constructor(token?: string) {
    const mapboxToken = token || process.env.MAPBOX_ACCESS_TOKEN;
    this.headers = {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${mapboxToken}`
    };
  }

  async callTool(name: string, args: any): Promise<string> {
    const request = {
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'tools/call',
      params: { name, arguments: args }
    };

    const response = await fetch(this.url, {
      method: 'POST',
      headers: this.headers,
      body: JSON.stringify(request)
    });

    const data = await response.json();

    if (data.error) {
      throw new Error(`MCP Error: ${data.error.message}`);
    }

    return data.result.content[0].text;
  }
}

// Initialize MCP connector
const mcp = new MapboxMCP();

// Create the coffee shop search tool
const searchCoffeeShopsTool = new DynamicStructuredTool({
  name: 'search_coffee_shops',
  description: `Find coffee shops near a specific location. Use when user wants to find coffee shops, cafes, or similar establishments.`,
  schema: z.object({
    location: z.tuple([z.number(), z.number()]).describe('Search center [longitude, latitude]'),
    category: z.string().default('coffee').describe('Category to search for')
  }) as any,
  func: async ({ location, category }: any) => {
    return await mcp.callTool('category_search_tool', {
      category: category || 'coffee',
      proximity: { 
        longitude: location[0], 
        latitude: location[1] 
      }
    });
  }
});

// Create agent
const llm = new ChatOpenAI({ 
  model: 'gpt-4', 
  temperature: 0 
});

const prompt = ChatPromptTemplate.fromMessages([
  ['system', `You are a location intelligence assistant specializing in finding places near specific locations.

  When searching for coffee shops:
  - Use the search_coffee_shops tool with the exact coordinates provided
  - Parse the results and present them in a user-friendly format
  - Include names, addresses, and any other relevant details from the search results`],
  ['human', '{input}'],
  new MessagesPlaceholder('agent_scratchpad')
]);

// @ts-ignore - Prevent TypeScript recursion issues with complex Zod schemas
const agent = await createToolCallingAgent({ 
  llm, 
  tools: [searchCoffeeShopsTool], 
  prompt 
});

const executor = new AgentExecutor({ 
  agent, 
  tools: [searchCoffeeShopsTool], 
  verbose: true 
});

// Find coffee shops near Times Square
// Note: Times Square coordinates are [-73.9855, 40.7580] (longitude, latitude)
