You can handle building taps using Mapbox's Featureset Interactions API with the Standard style. Here's how to implement building tap handling with highlighting:

## View System Implementation

```kotlin
import com.mapbox.maps.interactions.ClickInteraction
import com.mapbox.maps.interactions.featuresetinteraction.StandardBuildingsState

class MapActivity : AppCompatActivity() {
    private lateinit var mapView: MapView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_map)

        mapView = findViewById(R.id.mapView)
        mapView.mapboxMap.loadStyle(Style.STANDARD)

        setupBuildingInteractions()
    }

    private fun setupBuildingInteractions() {
        // Handle building taps
        mapView.mapboxMap.addInteraction(
            ClickInteraction.standardBuildings { building, context ->
                Log.d("BuildingTap", "Building tapped at: ${building.center}")

                // Highlight the tapped building
                mapView.mapboxMap.setFeatureState(
                    building,
                    StandardBuildingsState {
                        highlight(true)
                    }
                )

                true // Consume the tap event
            }
        )
    }

    override fun onStart() {
        super.onStart()
        mapView.onStart()
    }

    override fun onStop() {
        super.onStop()
        mapView.onStop()
    }

    override fun onDestroy() {
        super.onDestroy()
        mapView.onDestroy()
    }
}
```

## Jetpack Compose Implementation

