## Advanced Building Interaction Features

### Clear Previous Highlights

```kotlin
private var lastHighlightedBuilding: FeaturesetFeature<StandardBuildingsFeature>? = null

mapView.mapboxMap.addInteraction(
    ClickInteraction.standardBuildings { building, context ->
        // Clear previous highlight
        lastHighlightedBuilding?.let { previous ->
            mapView.mapboxMap.setFeatureState(
                previous,
                StandardBuildingsState {
                    highlight(false)
                }
            )
        }

        // Highlight new building
        mapView.mapboxMap.setFeatureState(
            building,
            StandardBuildingsState {
                highlight(true)
            }
        )

        lastHighlightedBuilding = building
        true
    }
)
```

### Access Building Properties

```kotlin
mapView.mapboxMap.addInteraction(
    ClickInteraction.standardBuildings { building, context ->
        // Access building feature properties
        val feature = building.feature
        Log.d("Building", "Properties: ${feature.properties()}")

        // Get building center point
        Log.d("Building", "Center: ${building.center}")

        mapView.mapboxMap.setFeatureState(
            building,
            StandardBuildingsState {
                highlight(true)
            }
        )

        true
    }
)
```

### Handle Map Clicks (Clear Highlights)

```kotlin
// Clear building highlights when tapping empty space
mapView.gestures.addOnMapClickListener { point ->
    lastHighlightedBuilding?.let { building ->
        mapView.mapboxMap.setFeatureState(
            building,
            StandardBuildingsState {
                highlight(false)
            }
        )
        lastHighlightedBuilding = null
    }
    false // Don't consume the event
}
```

## Key Points

1. **Use Standard Style**: Building interactions only work with `Style.STANDARD`
2. **FeatureState**: Use `StandardBuildingsState` to control building appearance
3. **Event Consumption**: Return `true` from the interaction to consume the tap event
4. **Highlight Property**: The `highlight(true)` property makes buildings visually stand out
5. **Feature Access**: Access building properties and geometry through the `building.feature` object

The Standard style automatically handles the visual appearance of highlighted buildings, making them more prominent on the map.

You should use **feature state** for efficient hover highlighting. This updates styling without modifying the source data, which is much more performant than re-uploading GeoJSON.

Here's the efficient pattern:

## Feature State Hover Pattern

```javascript
map.on('load', () => {
  // Add source with generateId: true (required for feature state)
  map.addSource('countries', {
    type: 'geojson',
    data: 'https://example.com/countries.geojson',
    generateId: true // This enables feature state
  });

  // Add fill layer with hover state styling
  map.addLayer({
    id: 'countries-fill',
    type: 'fill',
    source: 'countries',
    paint: {
      // Base choropleth color
      'fill-color': [
        'interpolate',
        ['linear'],
        ['get', 'population'],
        0, '#f0f9ff',
        10000000, '#7fcdff',
        50000000, '#0080ff',
        100000000, '#001f5c'
      ],
      'fill-opacity': [
        'case',
        ['boolean', ['feature-state', 'hover'], false],
        1.0,    // Full opacity on hover
        0.75    // Default opacity
      ]
    }
  });

  // Add stroke layer for hover effect
  map.addLayer({
    id: 'countries-stroke',
    type: 'line',
    source: 'countries',
    paint: {
      'line-color': [
        'case',
        ['boolean', ['feature-state', 'hover'], false],
        '#ffffff',  // White border on hover
        'transparent'  // No border normally
      ],
      'line-width': [
        'case',
        ['boolean', ['feature-state', 'hover'], false],
        3,  // Thick border on hover
        0   // No border normally
      ]
    }
  });

  // Track currently hovered feature
  let hoveredCountryId = null;

  // Mouse enter
  map.on('mousemove', 'countries-fill', (e) => {
    if (e.features.length > 0) {
      // Remove hover from previous feature
      if (hoveredCountryId !== null) {
        map.setFeatureState(
          { source: 'countries', id: hoveredCountryId },
          { hover: false }
        );
      }

      // Add hover to current feature
      hoveredCountryId = e.features[0].id;
      map.setFeatureState(
        { source: 'countries', id: hoveredCountryId },
        { hover: true }
      );

      // Change cursor
      map.getCanvas().style.cursor = 'pointer';
    }
  });

  // Mouse leave
  map.on('mouseleave', 'countries-fill', () => {
    if (hoveredCountryId !== null) {
      map.setFeatureState(
        { source: 'countries', id: hoveredCountryId },
        { hover: false }
      );
    }
    hoveredCountryId = null;
    map.getCanvas().style.cursor = '';
  });
});
```

## Alternative: Color-Based Hover

If you prefer to change the actual color on hover:

```javascript
map.addLayer({
  id: 'countries-fill',
  type: 'fill',
  source: 'countries',
  paint: {
    'fill-color': [
      'case',
      ['boolean', ['feature-state', 'hover'], false],
      // Hover color (brightened version)
      [
        'interpolate',
        ['linear'],
        ['get', 'population'],
        0, '#ffffff',      // Brighter colors
        10000000, '#b3e0ff',
        50000000, '#66ccff',
        100000000, '#0066cc'
      ],
      // Default choropleth colors
      [
        'interpolate',
        ['linear'],
        ['get', 'population'],
        0, '#f0f9ff',
        10000000, '#7fcdff',
        50000000, '#0080ff',
        100000000, '#001f5c'
      ]
    ],
    'fill-opacity': 0.75
  }
});
```

## Key Points

1. **`generateId: true`** - Required for feature state to work
2. **`feature-state`** - Access hover state in paint expressions
3. **Track `hoveredCountryId`** - Clean up previous hover states
4. **No data re-uploading** - Only paint properties change
5. **Smooth performance** - Works well with large datasets

This pattern is much more efficient than modifying source data because it only updates the rendering, not the geometry or feature data itself.

For this e-commerce delivery zone analysis, you need a **hybrid approach** combining routing APIs for accuracy with geometric tools for performance. Here's the most efficient strategy:

## Optimal Two-Step Approach

### Step 1: Create the 30-Minute Delivery Zone (Routing API)
```javascript
// Create accurate travel-time zone using routing
isochrone_tool({
  coordinates: {
    longitude: -97.7431,
    latitude: 30.2672
  },
  contours_minutes: [30],
  profile: "mapbox/driving-traffic" // Include traffic for accuracy
})
```

**Why routing API here:** Only routing knows actual road networks, traffic patterns, and realistic travel times from your Austin warehouse.

### Step 2: Check All 500 Addresses (Geometric Tool)
```javascript
// For each of your 500 customer addresses:
point_in_polygon_tool({
  point: {
    longitude: customerLongitude,
    latitude: customerLatitude
  },
  polygon: deliveryZoneFromStep1
})
```

**Why geometric tool here:** Pure containment checks are instant - you can process all 500 addresses in seconds with no API rate limits.

## Why This Hybrid Approach is Most Efficient

| Aspect | This Approach | Alternative (All Routing) | Alternative (All Geometric) |
|--------|---------------|--------------------------|---------------------------|
| **Accuracy** | ✅ Realistic travel times | ✅ Accurate but slow | ❌ Inaccurate (crow flies) |
| **Performance** | ✅ 1 API call + 500 instant checks | ❌ 500 API calls | ✅ Fast but wrong |
| **Cost** | ✅ Minimal API usage | ❌ High API usage | ✅ Free but useless |
| **Traffic Awareness** | ✅ Considers real traffic | ✅ Yes | ❌ No |

## Complete Implementation Strategy

### Phase 1: Geocode Customer Addresses (if needed)
```javascript
// If you only have street addresses, geocode them first
search_and_geocode_tool({
  query: "123 Main St, Austin, TX"
})
```

### Phase 2: Create Delivery Zone
```javascript
// Create the authoritative 30-minute zone
const deliveryZone = await isochrone_tool({
  coordinates: {
    longitude: -97.7431, // Austin warehouse
    latitude: 30.2672
  },
  contours_minutes: [30],
  profile: "mapbox/driving-traffic", // Consider current traffic
  generalize: 0.01 // Slightly simplify for faster containment checks
});
```

### Phase 3: Batch Process All Customers
```javascript
const deliverableCustomers = [];
const nonDeliverableCustomers = [];

for (const customer of customers) {
  const isDeliverable = await point_in_polygon_tool({
    point: {
      longitude: customer.longitude,
      latitude: customer.latitude
    },
    polygon: deliveryZone.features[0].geometry
  });

  if (isDeliverable.result) {
    deliverableCustomers.push(customer);
  } else {
    nonDeliverableCustomers.push(customer);
  }
}
```

## Performance Optimization Tips

### For 500 Addresses:
- **Total API calls:** 1 (just the isochrone)
- **Geometric checks:** 500 (instant, no API limits)
- **Total time:** ~2-5 seconds including network latency

### For Larger Scale (1000+ addresses):
Consider adding `simplify_tool` after the isochrone to reduce polygon complexity:

```javascript
const simplifiedZone = await simplify_tool({
  geometry: deliveryZone.features[0].geometry,
  tolerance: 0.001 // Balance accuracy vs speed
});
```

## Business Intelligence Add-Ons

### Visualize Results
```javascript
// Create a map showing the zone and customer distribution
static_map_image_tool({
  style: "mapbox://styles/mapbox/streets-v12",
  center: { longitude: -97.7431, latitude: 30.2672 },
  zoom: 10,
  overlays: [
    {
      type: "geojson",
      data: deliveryZone, // Show the 30-min zone
      style: { fillColor: "rgba(0,255,0,0.3)" }
    },
    {
      type: "geojson", 
      data: deliverableCustomers, // Show deliverable customers
      style: { markerColor: "green" }
    },
    {
      type: "geojson",
      data: nonDeliverableCustomers, // Show non-deliverable
      style: { markerColor: "red" }
    }
  ]
})
```

### Calculate Coverage Metrics
```javascript
// Get zone area for reporting
const zoneArea = await area_tool({
  geometry: deliveryZone.features[0].geometry
});

console.log(`Delivery zone covers ${zoneArea.area_km2} km²`);
console.log(`${deliverableCustomers.length} of ${customers.length} customers (${Math.round(deliverableCustomers.length/customers.length*100)}%) are in delivery zone`);
```

## Why Not Other Approaches?

### ❌ Matrix API for 500 addresses:
```javascript
// DON'T DO THIS - inefficient
matrix_tool({
  coordinates: [warehouse, ...500customers], // 501 coordinates
  profile: "mapbox/driving-traffic"
});
```
**Problems:** Matrix API has 25×25 limit, so you'd need 20+ API calls. Much slower and more expensive than the hybrid approach.

### ❌ Individual directions for each customer:
```javascript
// DON'T DO THIS - very inefficient  
for (customer of customers) {
  directions_tool({ coordinates: [warehouse, customer] }); // 500 API calls!
}
```
**Problems:** 500 API calls vs 1. Much slower, hits rate limits, expensive.

### ❌ Geometric buffer instead of isochrone:
```javascript
// DON'T DO THIS - inaccurate
buffer_tool({
  coordinates: warehouse,
  radius: estimatedDistance30min // Guess based on average speed
});
```
**Problems:** Roads aren't radial from Austin. Traffic varies by direction and time. Geographic distance ≠ travel time.

## Summary

**Most efficient approach for 500 customers:**
1. **One** `isochrone_tool` call → Creates accurate 30-minute zone
2. **500** `point_in_polygon_tool` calls → Instant geometric checks
3. **Optional:** `static_map_image_tool` → Visualize results

**Total time:** ~3 seconds  
**Total API calls:** 1-2  
**Accuracy:** High (considers real traffic and road networks)  
**Scalability:** Easily handles 1000+ addresses

This hybrid approach gives you routing-quality accuracy with geometric-tool performance - the best of both worlds for your e-commerce delivery zone analysis.

This is a perfect example of the fundamental difference between Google Maps and Mapbox GL JS approaches!

## Why This Happens

**Google Maps (Object-Oriented):**
- Each feature (polygon, marker) is an individual object
- `polygon.setMap(null)` removes that specific object
- Simple 1:1 relationship

**Mapbox GL JS (Data-Driven):**
- **Sources** contain the data
- **Layers** define how to visualize that data
- Multiple layers can reference the same source
- Must remove layers first, then source

## The Fix

You need to remove the layer(s) before removing the source:

```javascript
// Remove layer first
map.removeLayer('stores-layer');

// Then remove source
map.removeSource('stores');
```

## Complete Example

```javascript
// When adding (for context)
map.addSource('stores', {
  type: 'geojson',
  data: storesGeojson
});

map.addLayer({
  id: 'stores-layer',
  type: 'fill',
  source: 'stores', // Layer references the source
  paint: {
    'fill-color': '#ff0000',
    'fill-opacity': 0.5
  }
});

// When removing - ORDER MATTERS!
map.removeLayer('stores-layer');  // Remove layer first
map.removeSource('stores');       // Then remove source
```

## Helper Function for Clean Removal

```javascript
function removeLayerAndSource(map, sourceId, layerIds) {
  // Remove all layers using this source
  layerIds.forEach(layerId => {
    if (map.getLayer(layerId)) {
      map.removeLayer(layerId);
    }
  });

  // Then remove the source
  if (map.getSource(sourceId)) {
    map.removeSource(sourceId);
  }
}

// Usage
removeLayerAndSource(map, 'stores', ['stores-layer', 'stores-outline']);
```

## Why Multiple Layers?

You might have multiple layers for one source:

```javascript
map.addSource('stores', { /* data */ });

// Fill layer
map.addLayer({
  id: 'stores-fill',
  type: 'fill',
  source: 'stores',
  paint: { 'fill-color': '#ff0000' }
});

// Outline layer
map.addLayer({
  id: 'stores-outline', 
  type: 'line',
  source: 'stores',
  paint: { 'line-color': '#000000' }
});

// Must remove BOTH layers before removing source
map.removeLayer('stores-fill');
map.removeLayer('stores-outline');
map.removeSource('stores');
```

## Safety Check Version

```javascript
function safeRemoveLayerAndSource(map, sourceId, layerIds) {
  // Remove layers first
  layerIds.forEach(layerId => {
    if (map.getLayer(layerId)) {
      map.removeLayer(layerId);
    }
  });

  // Wait a tick, then remove source
  setTimeout(() => {
    if (map.getSource(sourceId)) {
      map.removeSource(sourceId);
    }
  }, 0);
}
```

## Finding All Layers Using a Source

If you're not sure which layers use a source:

```javascript
function getLayersUsingSource(map, sourceId) {
  const layers = map.getStyle().layers;
  return layers
    .filter(layer => layer.source === sourceId)
    .map(layer => layer.id);
}

// Usage
const layerIds = getLayersUsingSource(map, 'stores');
layerIds.forEach(id => map.removeLayer(id));
map.removeSource('stores');
```

**Key Takeaway:** In Mapbox, always remove layers before removing sources. This separation of data (sources) and visualization (layers) is more flexible but requires this two-step removal process.

Yes, there's a much better pattern! The flash happens because you're completely removing and re-adding the layer. Instead, you should keep the layer and update the source data, or use filtering. Here are three better approaches:

## Method 1: Update Source Data (Recommended)

Keep the layer, just update the source with filtered data:

```javascript
// Instead of remove/add cycle
function filterStores(category) {
  const filteredStores = {
    type: 'FeatureCollection',
    features: allStoresData.features.filter(store => 
      category === 'all' || store.properties.category === category
    )
  };

  // Smooth update - no flash!
  map.getSource('stores').setData(filteredStores);
}

// Initial setup (do this once)
map.addSource('stores', {
  type: 'geojson',
  data: allStoresData // All 1000 stores
});

map.addLayer({
  id: 'stores',
  type: 'circle', // or 'symbol'
  source: 'stores',
  paint: {
    'circle-radius': 8,
    'circle-color': '#ff0000'
  }
});

// Usage
filterStores('restaurant'); // Only restaurant stores show
filterStores('all'); // Show all stores
```

## Method 2: Use Layer Filtering (Most Performant)

Keep all data in the source, use Mapbox expressions to filter:

```javascript
// Setup once with all data
map.addSource('stores', {
  type: 'geojson',
  data: allStoresData // All 1000 stores stay in source
});

map.addLayer({
  id: 'stores',
  type: 'circle',
  source: 'stores',
  filter: ['==', ['get', 'category'], 'restaurant'], // Initial filter
  paint: {
    'circle-radius': 8,
    'circle-color': '#ff0000'
  }
});

// Filter function
function filterStores(category) {
  const filter = category === 'all' 
    ? null // Show all
    : ['==', ['get', 'category'], category];

  map.setFilter('stores', filter);
}
```

## Method 3: Multiple Category Layers

If you have a few categories and want different styling per category:

```javascript
const categories = ['restaurant', 'retail', 'service'];

// Create one layer per category
categories.forEach(category => {
  map.addLayer({
    id: `stores-${category}`,
    type: 'circle',
    source: 'stores',
    filter: ['==', ['get', 'category'], category],
    paint: {
      'circle-radius': 8,
      'circle-color': getCategoryColor(category)
    }
  });
});

// Show/hide categories
function filterStores(activeCategories) {
  categories.forEach(category => {
    const visibility = activeCategories.includes(category) ? 'visible' : 'none';
    map.setLayoutProperty(`stores-${category}`, 'visibility', visibility);
  });
}
```

## Performance Comparison

| Method | Performance | Use Case | Flash? |
|--------|------------|----------|---------|
| **setData()** | Good | Simple filtering | ❌ No |
| **setFilter()** | Best | Complex filters | ❌ No |
| **remove/add** | Worst | Never use | ✅ Yes |

## Why Your Current Approach Flashes

```javascript
// This causes flash:
map.removeLayer('stores'); // Layer disappears immediately
map.removeSource('stores');
// Brief moment with no layer visible ⚡ FLASH!
map.addSource('stores', newData);
map.addLayer(layerConfig); // Layer reappears
```

The gap between `removeLayer()` and `addLayer()` creates the visible flash.

## Advanced: Transition Effects

You can even add smooth transitions:

```javascript
map.addLayer({
  id: 'stores',
  type: 'circle',
  source: 'stores',
  paint: {
    'circle-radius': {
      type: 'exponential',
      property: ['get', 'importance'],
      default: 8
    },
    'circle-opacity': {
      duration: 300, // 300ms fade transition
      default: 0.8
    }
  }
});
```

**Bottom line:** Use `setData()` or `setFilter()` instead of the remove/add cycle. Your users will appreciate the smooth experience!

You're hitting a common Mapbox performance issue! Creating new `PointAnnotationManager` instances repeatedly is expensive and causes poor performance.

## The Problem

```swift
// ❌ Don't create new managers repeatedly
func updateMarkers() {
    let manager = mapView.annotations.makePointAnnotationManager()
    manager.annotations = markers
}
```

Each time you create a new manager, Mapbox has to:
- Initialize internal rendering resources
- Process all annotations from scratch
- Clean up the previous manager (eventually)

## The Solution

Create the manager **once** and reuse it:

```swift
class MapViewController: UIViewController {
    private var mapView: MapView!
    // ✅ Create once, store as property
    private var pointAnnotationManager: PointAnnotationManager!

    override func viewDidLoad() {
        super.viewDidLoad()
        setupMap()

        // Initialize manager once
        pointAnnotationManager = mapView.annotations.makePointAnnotationManager()
    }

    func updateMarkers() {
        // ✅ Just update the annotations array
        pointAnnotationManager.annotations = markers
    }
}
```

## SwiftUI Pattern

For SwiftUI, store the manager at the appropriate scope:

```swift
class MapStore: ObservableObject {
    private var pointAnnotationManager: PointAnnotationManager?

    func setupManager(for mapView: MapView) {
        if pointAnnotationManager == nil {
            pointAnnotationManager = mapView.annotations.makePointAnnotationManager()
        }
    }

    func updateMarkers(_ markers: [PointAnnotation]) {
        pointAnnotationManager?.annotations = markers
    }
}
```

## Additional Performance Tips

1. **Batch updates** instead of individual changes:
```swift
// ✅ Good - single batch update
pointAnnotationManager.annotations = newAnnotations

// ❌ Bad - multiple individual updates
for annotation in newAnnotations {
    pointAnnotationManager.annotations.append(annotation)
}
```

2. **Limit visible annotations** to viewport when dealing with many markers:
```swift
let visibleAnnotations = allAnnotations.filter { annotation in
    mapView.mapboxMap.coordinateBounds(for: mapView.bounds).contains(annotation.coordinate)
}
pointAnnotationManager.annotations = visibleAnnotations
```

3. **Use proper cleanup**:
```swift
deinit {
    // Manager will be cleaned up automatically, but good practice
    pointAnnotationManager = nil
}
```

This pattern should dramatically improve your performance when updating markers frequently!

The issue is that you're still using the DOM-based marker approach! While this is a direct translation from Google Maps, it's not the optimal pattern for Mapbox when dealing with many markers.

## The Problem

Both `google.maps.Marker()` and `mapboxgl.Marker()` create DOM elements for each marker. With 500 markers, you're creating 500 DOM nodes, which causes performance issues:

- DOM manipulation is expensive
- Each marker needs individual event handling
- Browser rendering becomes sluggish

## The Solution: Data-Driven Approach

Convert to Mapbox's data-driven pattern using GeoJSON sources and symbol layers. This renders markers using WebGL instead of DOM, giving you massive performance gains:

```javascript
// ❌ Current approach (slow with 500+ markers)
stores.forEach(store => {
  new mapboxgl.Marker()
    .setLngLat([store.lng, store.lat])
    .addTo(map);
});

// ✅ Optimized approach (fast with 1000s of markers)
map.on('load', () => {
  // Convert your stores to GeoJSON
  const geojsonData = {
    type: 'FeatureCollection',
    features: stores.map(store => ({
      type: 'Feature',
      geometry: {
        type: 'Point',
        coordinates: [store.lng, store.lat] // Note: lng, lat order!
      },
      properties: {
        name: store.name,
        address: store.address,
        phone: store.phone,
        id: store.id
        // Include any other store data you need
      }
    }))
  };

  // Add source
  map.addSource('stores', {
    type: 'geojson',
    data: geojsonData
  });

  // Add layer for store markers
  map.addLayer({
    id: 'store-markers',
    type: 'circle', // or 'symbol' for custom icons
    source: 'stores',
    paint: {
      'circle-radius': 8,
      'circle-color': '#007cbf',
      'circle-stroke-color': '#fff',
      'circle-stroke-width': 2
    }
  });

  // Add click handler for all markers
  map.on('click', 'store-markers', (e) => {
    const store = e.features[0].properties;

    // Create popup
    new mapboxgl.Popup()
      .setLngLat(e.lngLat)
      .setHTML(`
        <h3>${store.name}</h3>
        <p>${store.address}</p>
        <p>${store.phone}</p>
      `)
      .addTo(map);
  });

  // Change cursor on hover
  map.on('mouseenter', 'store-markers', () => {
    map.getCanvas().style.cursor = 'pointer';
  });

  map.on('mouseleave', 'store-markers', () => {
    map.getCanvas().style.cursor = '';
  });
});
```

## Performance Benefits

This approach gives you:

- **WebGL rendering** instead of DOM manipulation
- **Single event listener** instead of 500 individual listeners
- **Better performance** with 1000s of markers
- **Built-in clustering** capabilities
- **Dynamic styling** based on data properties

## Adding Custom Icons

If you need custom store icons:

```javascript
// Load your store icon
map.loadImage('/path/to/store-icon.png', (error, image) => {
  if (error) throw error;

  map.addImage('store-icon', image);

  // Use symbol layer instead of circle
  map.addLayer({
    id: 'store-markers',
    type: 'symbol',
    source: 'stores',
    layout: {
      'icon-image': 'store-icon',
      'icon-size': 1,
      'icon-allow-overlap': true
    }
  });
});
```

## Adding Clustering (Bonus)

With many stores, clustering improves UX:

```javascript
map.addSource('stores', {
  type: 'geojson',
  data: geojsonData,
  cluster: true,           // Enable clustering
  clusterMaxZoom: 14,      // Max zoom to cluster points
  clusterRadius: 50        // Radius of each cluster
});

// Add cluster circles
map.addLayer({
  id: 'clusters',
  type: 'circle',
  source: 'stores',
  filter: ['has', 'point_count'],
  paint: {
    'circle-color': [
      'step',
      ['get', 'point_count'],
      '#51bbd6', 100,
      '#f1f075', 750,
      '#f28cb1'
    ],
    'circle-radius': [
      'step',
      ['get', 'point_count'],
      20, 100, 30, 750, 40
    ]
  }
});

// Add cluster count labels
map.addLayer({
  id: 'cluster-count',
  type: 'symbol',
  source: 'stores',
  filter: ['has', 'point_count'],
  layout: {
    'text-field': '{point_count_abbreviated}',
    'text-size': 12
  }
});

// Individual store markers (unclustered)
map.addLayer({
  id: 'unclustered-stores',
  type: 'circle',
  source: 'stores',
  filter: ['!', ['has', 'point_count']],
  paint: {
    'circle-color': '#007cbf',
    'circle-radius': 8
  }
});
```

## When to Use Each Approach

**Use `mapboxgl.Marker()` when:**
- < 100 markers
- Need complex HTML content in markers
- Need individual marker animations

**Use data-driven layers when:**
- 100+ markers (like your 500 stores)
- Want best performance
- Need clustering
- Want consistent styling

Your store locator will be much more responsive with this data-driven approach!

You can use Mapbox's Interactions API with the `.standardPoi` featureset to detect taps on POIs like coffee shops and restaurants. Here are both SwiftUI and UIKit patterns:

## SwiftUI Pattern

```swift
import SwiftUI
import MapboxMaps

struct MapView: View {
    @State private var viewport: Viewport = .camera(
        center: CLLocationCoordinate2D(latitude: 37.7749, longitude: -122.4194),
        zoom: 12
    )
    @State private var selectedPoi: String?

    var body: some View {
        Map(viewport: $viewport) {
            // Tap interaction for POI features
            TapInteraction(.standardPoi) { poi, context in
                handlePoiTap(poi)
                return true // Stop event propagation
            }
        }
        .mapStyle(.standard)
        .alert("POI Tapped", isPresented: .constant(selectedPoi != nil)) {
            Button("OK") { selectedPoi = nil }
        } message: {
            if let poiName = selectedPoi {
                Text(poiName)
            }
        }
    }

    private func handlePoiTap(_ poi: StandardPoiFeature) {
        let name = poi.name ?? "Unknown POI"
        let category = poi.poiCategory ?? "Unknown category"

        print("Tapped POI: \(name)")
        print("Category: \(category)")
        print("Coordinate: \(poi.coordinate)")

        selectedPoi = "\(name)\nCategory: \(category)"
    }
}
```

## UIKit Pattern

```swift
import UIKit
import MapboxMaps

class MapViewController: UIViewController {
    private var mapView: MapView!
    private var poiInteractionToken: InteractionToken?

    override func viewDidLoad() {
        super.viewDidLoad()
        setupMap()
        setupPoiInteraction()
    }

    private func setupMap() {
        let options = MapInitOptions(
            cameraOptions: CameraOptions(
                center: CLLocationCoordinate2D(latitude: 37.7749, longitude: -122.4194),
                zoom: 12
            )
        )

        mapView = MapView(frame: view.bounds, mapInitOptions: options)
        mapView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        view.addSubview(mapView)

        mapView.mapboxMap.loadStyle(.standard)
    }

    private func setupPoiInteraction() {
        poiInteractionToken = mapView.mapboxMap.addInteraction(
            TapInteraction(.standardPoi) { [weak self] poi, context in
                self?.handlePoiTap(poi)
                return true // Stop event propagation
            }
        )
    }

    private func handlePoiTap(_ poi: StandardPoiFeature) {
        let name = poi.name ?? "Unknown POI"
        let category = poi.poiCategory ?? "Unknown category"

        print("Tapped POI: \(name)")
        print("Category: \(category)")
        print("Coordinate: \(poi.coordinate)")

        // Show alert with POI info
        let alert = UIAlertController(
            title: "POI Tapped", 
            message: "\(name)\nCategory: \(category)", 
            preferredStyle: .alert
        )
        alert.addAction(UIAlertAction(title: "OK", style: .default))
        present(alert, animated: true)
    }

    deinit {
        // Clean up interaction
        poiInteractionToken?.cancel()
    }
}
```

## Key Points

**Available POI Properties:**
- `poi.name` - POI name (e.g. "Starbucks")
- `poi.poiCategory` - Category (e.g. "coffee", "restaurant") 
- `poi.coordinate` - Location coordinate
- `poi.id` - Unique identifier

**Common POI Categories:**
- `"restaurant"`, `"cafe"`, `"coffee"`
- `"gas_station"`, `"hospital"`, `"school"`
- `"bank"`, `"hotel"`, `"shopping"`

**Return `true`** from the interaction handler to stop event propagation and prevent the tap from triggering other map interactions.

**Performance:** The Interactions API is optimized for the Standard style and works directly with Mapbox's built-in POI data - no additional data loading required.

This approach gives you typed access to POI features with all their properties, making it easy to build rich interactive experiences around points of interest.

