### 2. Real-Time Tracking Loop (Direct Turf.js)

```javascript
// Your main tracking loop - runs every 2 seconds
class FleetTracker {
  constructor(restrictedZones) {
    this.zones = restrictedZones; // GeoJSON polygons
    this.truckStates = new Map(); // Track which zones trucks are in
  }

  processGPSUpdate(truckId, coordinate) {
    const previousState = this.truckStates.get(truckId) || new Set();
    const currentState = new Set();

    // Check each zone (fast geometric operation)
    for (const zone of this.zones) {
      const isInside = booleanPointInPolygon(
        [coordinate.longitude, coordinate.latitude],
        zone.geometry
      );

      if (isInside) {
        currentState.add(zone.id);
      }

      // Detect zone entry/exit
      const wasInside = previousState.has(zone.id);
      if (isInside && !wasInside) {
        this.handleZoneEntry(truckId, zone, coordinate);
      } else if (!isInside && wasInside) {
        this.handleZoneExit(truckId, zone, coordinate);
      }
    }

    this.truckStates.set(truckId, currentState);
  }

  handleZoneEntry(truckId, zone, coordinate) {
    console.log(`Truck ${truckId} entered ${zone.name}`);
    // Send alerts, log violations, etc.
    this.logViolation(truckId, zone, 'ENTERED', coordinate);
  }

  handleZoneExit(truckId, zone, coordinate) {
    console.log(`Truck ${truckId} left ${zone.name}`);
    this.logViolation(truckId, zone, 'EXITED', coordinate);
  }
}
```

