I'll show you how to use the `point_in_polygon_tool` with Mapbox MCP in Mastra to check if your Los Angeles location falls within a service polygon.

```typescript
import { Agent } from '@mastra/core/agent';
import { createTool } from '@mastra/core/tools';
import { z } from 'zod';

class MapboxMCP {
  private url = 'https://mcp.mapbox.com/mcp';
  private headers: Record<string, string>;

  constructor(token?: string) {
    const mapboxToken = token || process.env.MAPBOX_ACCESS_TOKEN;
    this.headers = {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${mapboxToken}`
    };
  }

  async callTool(toolName: string, params: any): Promise<any> {
    const request = {
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'tools/call',
      params: { name: toolName, arguments: params }
    };

    const response = await fetch(this.url, {
      method: 'POST',
      headers: this.headers,
      body: JSON.stringify(request)
    });

    const data = await response.json();

    if (data.error) {
      throw new Error(`MCP Error: ${data.error.message}`);
    }

    return JSON.parse(data.result.content[0].text);
  }
}

const mcp = new MapboxMCP();

// Create the point-in-polygon tool
const pointInPolygonTool = createTool({
  id: 'check-service-area',
  description: 'Check if a point (user location) falls within a service polygon area',
  inputSchema: z.object({
    userLocation: z.object({
      longitude: z.number(),
      latitude: z.number()
    }),
    servicePolygon: z.object({
      type: z.literal('Polygon'),
      coordinates: z.array(z.array(z.array(z.number())))
    })
  }),
  execute: async ({ userLocation, servicePolygon }) => {
    const result = await mcp.callTool('point_in_polygon_tool', {
      point: userLocation,
      polygon: servicePolygon
    });
    return result; // Returns boolean true/false
  }
});

// Create agent with the tool
const serviceAreaAgent = new Agent({
  id: 'service-area-agent',
  name: 'Service Area Checker',
  instructions: `You help determine if user locations fall within service areas. 
  Use the check-service-area tool to verify if a point is within a polygon.`,
  model: 'openai/gpt-4',
  tools: {
    pointInPolygonTool
  }
});

// Example usage with your Los Angeles location
async function checkLAService() {
  // Your LA location: 34.0522° N, 118.2437° W
  const userLocation = {
    longitude: -118.2437,  // Note: longitude is negative for West
    latitude: 34.0522
  };

  // Example service polygon (downtown LA area)
  const servicePolygon = {
    type: 'Polygon' as const,
    coordinates: [[
      [-118.3000, 34.0000],  // SW corner
      [-118.2000, 34.0000],  // SE corner  
      [-118.2000, 34.1000],  // NE corner
      [-118.3000, 34.1000],  // NW corner
      [-118.3000, 34.0000]   // Close polygon
    ]]
  };

  // Check if user is in service area
  const result = await serviceAreaAgent.generate([{
    role: 'user',
    content: `Check if the user at coordinates ${userLocation.latitude}°N, ${userLocation.longitude}°W is within our service area.`
  }], {
    // Pass the data the agent needs
    toolArguments: {
      userLocation,
      servicePolygon
    }
  });

  console.log('Service area check result:', result);
}

// Alternative: Direct tool usage without agent conversation
async function directCheck() {
  const userLocation = {
    longitude: -118.2437,
    latitude: 34.0522
  };

  const servicePolygon = {
    type: 'Polygon' as const,
    coordinates: [[
      [-118.3000, 34.0000],
      [-118.2000, 34.0000],
      [-118.2000, 34.1000],
      [-118.3000, 34.1000],
      [-118.3000, 34.0000]
    ]]
  };

  const isInServiceArea = await mcp.callTool('point_in_polygon_tool', {
    point: userLocation,
    polygon: servicePolygon
  });

  console.log('User is in service area:', isInServiceArea);
  return isInServiceArea;
}

// Run the check
checkLAService();
```

**Key Points:**

1. **Coordinate Format**: Note that longitude comes first, and for Los Angeles (West coast), longitude is negative: `[-118.2437, 34.0522]`

2. **Polygon Structure**: The polygon must be a valid GeoJSON Polygon with coordinates as `[longitude, latitude]` arrays, and the first/last points must be identical to close the polygon.

3. **Tool Benefits**: This is an **offline tool** - it uses Turf.js under the hood, so it's instant and free (no API calls).

**Real-world Service Area Example:**

