## Step 1: MCP Connector Class

First, let's create a connector to the hosted Mapbox MCP server:

```python
import requests
import json
import os
from typing import Dict, Any, Optional

class MapboxMCP:
    """Connector to Mapbox MCP Server."""

    def __init__(self, token: Optional[str] = None):
        self.url = 'https://mcp.mapbox.com/mcp'
        self.headers = {'Content-Type': 'application/json'}

        # Use token from parameter or environment
        token = token or os.getenv('MAPBOX_ACCESS_TOKEN')
        if not token:
            raise ValueError("Mapbox access token required")

        self.headers['Authorization'] = f'Bearer {token}'

    def call_tool(self, tool_name: str, params: Dict[str, Any]) -> str:
        """Call MCP tool and return result."""
        request = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'tools/call',
            'params': {
                'name': tool_name,
                'arguments': params
            }
        }

        try:
            response = requests.post(
                self.url,
                headers=self.headers,
                json=request,
                timeout=30
            )
            response.raise_for_status()

            data = response.json()

            if 'error' in data:
                raise RuntimeError(f"MCP error: {data['error']['message']}")

            return data['result']['content'][0]['text']

        except requests.exceptions.RequestException as e:
            raise RuntimeError(f"Failed to call MCP tool {tool_name}: {e}")
