## Step 2: Geospatial Helper Functions

Create utility functions for common geospatial operations:

```python
from dataclasses import dataclass
from typing import List, Tuple
import re

@dataclass
class Location:
    name: str
    coordinates: Tuple[float, float]  # (longitude, latitude)

class GeospatialHelper:
    """Helper functions for geospatial operations."""

    def __init__(self, mcp: MapboxMCP):
        self.mcp = mcp

    def parse_location(self, location_text: str) -> Tuple[float, float]:
        """Parse location text to coordinates."""

        # Check if it's already coordinates
        coord_pattern = r'[-+]?\d*\.?\d+,\s*[-+]?\d*\.?\d+'
        if re.match(coord_pattern, location_text):
            coords = location_text.split(',')
            return (float(coords[0].strip()), float(coords[1].strip()))

        # Otherwise geocode the text
        result = self.mcp.call_tool('search_and_geocode_tool', {
            'query': location_text
        })

        # Parse the geocoding result
        geocode_data = json.loads(result)
        if geocode_data and len(geocode_data) > 0:
            coords = geocode_data[0]['center']
            return (coords[0], coords[1])  # [lng, lat]

        raise ValueError(f"Could not find location: {location_text}")

    def search_nearby_places(
        self, 
        category: str, 
        location: Tuple[float, float],
        max_distance_miles: float = None
    ) -> List[Dict[str, Any]]:
        """Search for places by category near a location."""

        result = self.mcp.call_tool('category_search_tool', {
            'category': category,
            'proximity': {
                'longitude': location[0], 
                'latitude': location[1]
            }
        })

        places = json.loads(result)

        # Filter by distance if specified
        if max_distance_miles:
            filtered_places = []
            for place in places:
                distance = self.mcp.call_tool('distance_tool', {
                    'from': {
                        'longitude': location[0], 
                        'latitude': location[1]
                    },
                    'to': {
                        'longitude': place['coordinates'][0],
                        'latitude': place['coordinates'][1]
                    },
                    'units': 'miles'
                })

                if float(distance) <= max_distance_miles:
                    place['distance_miles'] = float(distance)
                    filtered_places.append(place)

            return sorted(filtered_places, key=lambda x: x['distance_miles'])

        return places

    def get_walking_time(
        self, 
        from_location: Tuple[float, float], 
        to_location: Tuple[float, float]
    ) -> Dict[str, Any]:
        """Get walking directions and time."""

        result = self.mcp.call_tool('directions_tool', {
            'coordinates': [
                {
                    'longitude': from_location[0],
                    'latitude': from_location[1]
                },
                {
                    'longitude': to_location[0],
                    'latitude': to_location[1]
                }
            ],
            'routing_profile': 'mapbox/walking'
        })

        directions = json.loads(result)
        return {
            'duration_minutes': directions['duration'] / 60,
            'distance_miles': directions['distance'] * 0.000621371,  # meters to miles
            'geometry': directions['geometry']
        }

    def find_reachable_area(
        self,
        location: Tuple[float, float],
        minutes: int,
        profile: str = 'mapbox/walking'
    ) -> Dict[str, Any]:
        """Get isochrone (reachable area) from a location."""

        result = self.mcp.call_tool('isochrone_tool', {
            'coordinates': {
                'longitude': location[0],
                'latitude': location[1]
            },
            'contours_minutes': [minutes],
            'profile': profile
        })

        return json.loads(result)
```

## Step 3: Query Parser & Tool Router

Create a component to understand natural language queries and route to appropriate tools:

```python
import re
from typing import Optional, Dict, Any

class QueryParser:
    """Parse natural language geospatial queries."""

    def __init__(self):
        self.patterns = {
            'walking_time_search': r'(restaurants?|coffee|food|shops?|stores?|bars?|hotels?).*within (\d+) minutes? walking.*from (.+)',
            'nearby_search': r'(restaurants?|coffee|food|shops?|stores?|bars?|hotels?).*near (.+)',
            'travel_time': r'how long.*walk.*from (.+) to (.+)',
            'distance': r'how far.*from (.+) to (.+)',
        }

        self.category_mapping = {
            'restaurant': 'restaurant',
            'restaurants': 'restaurant', 
            'coffee': 'coffee_shop',
            'food': 'restaurant',
            'shop': 'retail',
            'shops': 'retail',
            'store': 'retail',
            'stores': 'retail',
            'bar': 'bar',
            'bars': 'bar',
            'hotel': 'hotel',
            'hotels': 'hotel'
        }

    def parse_query(self, query: str) -> Dict[str, Any]:
        """Parse natural language query into structured request."""

        query = query.lower().strip()

        # Pattern: "restaurants within 15 minutes walking from Union Square"
        match = re.search(self.patterns['walking_time_search'], query)
        if match:
            category_raw, minutes, location = match.groups()
            category = self.category_mapping.get(category_raw, category_raw)
            return {
                'type': 'walking_time_search',
                'category': category,
                'location': location.strip(),
                'max_minutes': int(minutes)
            }

        # Pattern: "restaurants near Union Square"
        match = re.search(self.patterns['nearby_search'], query)
        if match:
            category_raw, location = match.groups()
            category = self.category_mapping.get(category_raw, category_raw)
            return {
                'type': 'nearby_search',
                'category': category,
                'location': location.strip()
            }

        # Pattern: "how long to walk from A to B"
        match = re.search(self.patterns['travel_time'], query)
        if match:
            from_loc, to_loc = match.groups()
            return {
                'type': 'travel_time',
                'from_location': from_loc.strip(),
                'to_location': to_loc.strip()
            }

        # Pattern: "how far from A to B"
        match = re.search(self.patterns['distance'], query)
        if match:
            from_loc, to_loc = match.groups()
            return {
                'type': 'distance',
                'from_location': from_loc.strip(),
                'to_location': to_loc.strip()
            }

        return {'type': 'unknown', 'query': query}
```

## Step 4: Main AI Agent

Now, let's build the main agent that orchestrates everything:

```python
class GeospatialAgent:
    """AI agent for geospatial queries."""

    def __init__(self, mapbox_token: Optional[str] = None):
        self.mcp = MapboxMCP(mapbox_token)
        self.geo_helper = GeospatialHelper(self.mcp)
        self.parser = QueryParser()

    def answer_query(self, query: str) -> str:
        """Answer a natural language geospatial query."""

        try:
            # Parse the query
            parsed = self.parser.parse_query(query)

            if parsed['type'] == 'walking_time_search':
                return self._handle_walking_time_search(parsed)
            elif parsed['type'] == 'nearby_search':
                return self._handle_nearby_search(parsed)
            elif parsed['type'] == 'travel_time':
                return self._handle_travel_time(parsed)
            elif parsed['type'] == 'distance':
                return self._handle_distance(parsed)
            else:
                return f"I'm not sure how to help with: {query}. Try asking about restaurants, travel time, or distance between places."

        except Exception as e:
            return f"Sorry, I encountered an error: {str(e)}"

    def _handle_walking_time_search(self, parsed: Dict[str, Any]) -> str:
        """Handle 'places within X minutes walking' queries."""

        # Get location coordinates
        location = self.geo_helper.parse_location(parsed['location'])

        # Get isochrone (reachable area)
        isochrone = self.geo_helper.find_reachable_area(
            location, 
            parsed['max_minutes'], 
            'mapbox/walking'
        )

        # Search for places
        places = self.geo_helper.search_nearby_places(
            parsed['category'], 
            location
        )

        # Filter places within walking time
        reachable_places = []
        for place in places[:10]:  # Limit to first 10 results
            place_coords = (place['coordinates'][0], place['coordinates'][1])

            # Check if place is within isochrone
            in_area = self.mcp.call_tool('point_in_polygon_tool', {
                'point': {
                    'longitude': place_coords[0],
                    'latitude': place_coords[1]
                },
                'polygon': isochrone['features'][0]['geometry']
            })

            if json.loads(in_area):
                # Get exact walking time
                walking_info = self.geo_helper.get_walking_time(location, place_coords)
                place['walking_minutes'] = round(walking_info['duration_minutes'], 1)
                place['walking_distance'] = round(walking_info['distance_miles'], 2)
                reachable_places.append(place)

        # Format response
        if not reachable_places:
            return f"I couldn't find any {parsed['category']}s within {parsed['max_minutes']} minutes walking from {parsed['location']}."

        # Sort by walking time
        reachable_places.sort(key=lambda x: x['walking_minutes'])

        response = f"Here are {parsed['category']}s within {parsed['max_minutes']} minutes walking from {parsed['location']}:\n\n"

        for i, place in enumerate(reachable_places[:5], 1):  # Top 5 results
            response += f"{i}. **{place['name']}**\n"
            if 'address' in place:
                response += f"   Address: {place['address']}\n"
            response += f"   Walking time: {place['walking_minutes']} minutes\n"
            response += f"   Distance: {place['walking_distance']} miles\n\n"

        return response

    def _handle_nearby_search(self, parsed: Dict[str, Any]) -> str:
        """Handle 'places near location' queries."""

        location = self.geo_helper.parse_location(parsed['location'])
        places = self.geo_helper.search_nearby_places(parsed['category'], location)

        if not places:
            return f"I couldn't find any {parsed['category']}s near {parsed['location']}."

        response = f"Here are {parsed['category']}s near {parsed['location']}:\n\n"

        for i, place in enumerate(places[:5], 1):
            response += f"{i}. **{place['name']}**\n"
            if 'address' in place:
                response += f"   Address: {place['address']}\n\n"

        return response

    def _handle_travel_time(self, parsed: Dict[str, Any]) -> str:
        """Handle travel time queries."""

