## Step 4: Calculate Distances and Sort

```javascript
function sortStoresByDistance() {
  if (!userLocation) return;

  // Calculate distances using Turf.js
  const storesWithDistance = stores.features.map((store) => {
    const distance = turf.distance(
      turf.point(userLocation),
      turf.point(store.geometry.coordinates),
      { units: 'miles' }
    );

    return {
      ...store,
      properties: {
        ...store.properties,
        distance: Math.round(distance * 10) / 10 // Round to 1 decimal
      }
    };
  });

  // Sort by distance (closest first)
  storesWithDistance.sort((a, b) => a.properties.distance - b.properties.distance);

  // Update the stores object
  stores.features = storesWithDistance;

  // Rebuild the sidebar listing
  rebuildLocationList();

  // Optionally fit map to show user + nearby stores
  fitMapToUserAndStores(5); // Show nearest 5 stores
}

function rebuildLocationList() {
  const listingContainer = document.getElementById('listings');
  listingContainer.innerHTML = '';

  stores.features.forEach((store) => {
    const listing = listingContainer.appendChild(document.createElement('div'));
    listing.id = `listing-${store.properties.id}`;
    listing.className = 'listing';

    const link = listing.appendChild(document.createElement('a'));
    link.href = '#';
    link.className = 'title';
    link.innerHTML = store.properties.name;

    const details = listing.appendChild(document.createElement('div'));
    details.innerHTML = `
      ${store.properties.distance ? 
        `<p class="distance">${store.properties.distance} mi away</p>` : 
        ''
      }
      <p>${store.properties.address}</p>
      <p>${store.properties.phone || ''}</p>
    `;

    link.addEventListener('click', (e) => {
      e.preventDefault();
      flyToStore(store);
      createPopup(store);
      highlightListing(store.properties.id);
    });
  });
}
