function filterByDistance(maxDistance) {
  if (maxDistance === 'all') {
    rebuildLocationList();
    return;
  }

  const filtered = stores.features.filter(store => 
    !store.properties.distance || store.properties.distance <= maxDistance
  );

  // Temporarily update features for display
  const originalFeatures = stores.features;
  stores.features = filtered;
  rebuildLocationList();
  stores.features = originalFeatures; // Restore original
}
