## Step 2: Implement the pulse animation

```javascript
function startPulseAnimation() {
  const duration = 2000; // 2 seconds per pulse
  const maxRadius = 30; // Maximum ring size
  const minRadius = 12; // Starting ring size

  function animate() {
    const start = performance.now();

    function frame(time) {
      const elapsed = (time - start) % duration;
      const progress = elapsed / duration;

      // Calculate current radius (ease-out animation)
      const currentRadius = minRadius + (maxRadius - minRadius) * progress;

      // Calculate current opacity (fade from 0.3 to 0)
      const currentOpacity = 0.3 * (1 - progress);

      // Update the circle properties
      map.setPaintProperty('customer-pulse', 'circle-radius', currentRadius);
      map.setPaintProperty('customer-pulse', 'circle-opacity', currentOpacity);

      // Continue animation
      requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
  }

  animate();
}

// Start the animation when the map loads
map.on('load', () => {
  startPulseAnimation();
});
```

## Step 3: Enhanced version with easing

For a more polished sonar-like effect, use easing functions:

```javascript
function startSonarPulse() {
  const duration = 2500; // Slightly longer for smoother effect
  const maxRadius = 35;
  const minRadius = 12;

  // Easing function for smooth animation
  function easeOut(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  function animate() {
    const start = performance.now();

    function frame(time) {
      const elapsed = (time - start) % duration;
      const progress = elapsed / duration;
      const easedProgress = easeOut(progress);

      // Radius grows with easing
      const currentRadius = minRadius + (maxRadius - minRadius) * easedProgress;

      // Opacity fades more gradually at first, then quickly
      const opacityProgress = Math.pow(progress, 2);
      const currentOpacity = 0.4 * (1 - opacityProgress);

      map.setPaintProperty('customer-pulse', 'circle-radius', currentRadius);
      map.setPaintProperty('customer-pulse', 'circle-opacity', currentOpacity);

      requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
  }

  animate();
}
```

## Step 4: Multiple rings for enhanced sonar effect

For a more dramatic sonar effect with multiple overlapping rings:

```javascript
// Add multiple pulse layers
const pulseLayerCount = 3;

for (let i = 0; i < pulseLayerCount; i++) {
  map.addLayer({
    id: `customer-pulse-${i}`,
    type: 'circle',
    source: 'customer-location',
    paint: {
      'circle-radius': 12,
      'circle-color': '#4caf50',
      'circle-opacity': 0
    }
  });
}

function startMultiRingPulse() {
  const duration = 2000;
  const maxRadius = 40;
  const minRadius = 12;
  const ringDelay = duration / pulseLayerCount; // Stagger the rings

  function animate() {
    const start = performance.now();

    function frame(time) {
      for (let i = 0; i < pulseLayerCount; i++) {
        const elapsed = (time - start + (i * ringDelay)) % duration;
        const progress = elapsed / duration;

        if (progress >= 0) {
          const currentRadius = minRadius + (maxRadius - minRadius) * progress;
          const currentOpacity = 0.3 * (1 - progress);

          map.setPaintProperty(`customer-pulse-${i}`, 'circle-radius', currentRadius);
          map.setPaintProperty(`customer-pulse-${i}`, 'circle-opacity', currentOpacity);
        }
      }

      requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
  }

  animate();
}
```

## Step 5: Control the animation

Add methods to start/stop the animation as needed:

```javascript
class DeliveryMapController {
  constructor(map) {
    this.map = map;
    this.animationId = null;
    this.isAnimating = false;
  }

  startPulse() {
    if (this.isAnimating) return;

    this.isAnimating = true;
    const duration = 2000;
    const maxRadius = 30;
    const minRadius = 12;

    const animate = () => {
      if (!this.isAnimating) return;

      const start = performance.now();

      const frame = (time) => {
        if (!this.isAnimating) return;

        const elapsed = (time - start) % duration;
        const progress = elapsed / duration;

        const currentRadius = minRadius + (maxRadius - minRadius) * progress;
        const currentOpacity = 0.3 * (1 - progress);

        this.map.setPaintProperty('customer-pulse', 'circle-radius', currentRadius);
        this.map.setPaintProperty('customer-pulse', 'circle-opacity', currentOpacity);

        this.animationId = requestAnimationFrame(frame);
      };

      this.animationId = requestAnimationFrame(frame);
    };

    animate();
  }

  stopPulse() {
    this.isAnimating = false;
    if (this.animationId) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
    // Hide the pulse
    this.map.setPaintProperty('customer-pulse', 'circle-opacity', 0);
  }

  updateCustomerLocation(newCoordinates) {
    this.map.getSource('customer-location').setData({
      type: 'FeatureCollection',
      features: [{
        type: 'Feature',
        geometry: {
          type: 'Point',
          coordinates: newCoordinates
        }
      }]
    });
  }
}

// Usage
const deliveryMap = new DeliveryMapController(map);

// Start pulsing when order is placed
deliveryMap.startPulse();

// Stop pulsing when delivered
deliveryMap.stopPulse();
```

## Performance Tips

1. **Throttle updates**: Update at 30fps instead of 60fps for better performance
2. **Pause when not visible**: Stop animation when map is not in viewport
3. **Clean up**: Always stop animations when removing markers

```javascript
// Throttled version (30fps)
const targetFPS = 30;
const frameInterval = 1000 / targetFPS;
let lastFrameTime = 0;

function frame(time) {
  if (time - lastFrameTime >= frameInterval) {
    // Update animation
    lastFrameTime = time;
  }
  requestAnimationFrame(frame);
}
```

This approach gives you a smooth, performant pulsing circle animation that's perfect for delivery location indicators. The animation runs entirely on the GPU through Mapbox GL JS, making it much more efficient than HTML-based animations.

