results.modelResponse:
The issue is that you're recreating the entire map instance every time `mapStyle` changes. This causes the reset, flash, and loss of markers. Instead, you should **initialize the map once** and then use `map.setStyle()` to change styles dynamically.

Here's the corrected pattern:

```jsx
import { useRef, useEffect } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';

function MapView({ mapStyle }) {
  const mapRef = useRef(null);
  const containerRef = useRef(null);

  // Initialize map once with empty dependency array
  useEffect(() => {
    mapboxgl.accessToken = import.meta.env.VITE_MAPBOX_ACCESS_TOKEN;

    mapRef.current = new mapboxgl.Map({
      container: containerRef.current,
      style: mapStyle, // Use initial mapStyle
      center: [-122.4194, 37.7749],
      zoom: 12
    });

    return () => mapRef.current.remove();
  }, []); // Empty array = initialize once

  // Separate effect to handle style changes
  useEffect(() => {
    if (mapRef.current && mapRef.current.isStyleLoaded()) {
      mapRef.current.setStyle(mapStyle);
    }
  }, [mapStyle]);

  return <div ref={containerRef} style={{ height: '100vh' }} />;
}
```

**Key changes:**

1. **Initialize once**: First `useEffect` has empty dependency array `[]`
2. **Update style separately**: Second `useEffect` watches `mapStyle` and calls `map.setStyle()`
3. **Check if loaded**: `isStyleLoaded()` prevents calling `setStyle()` before map is ready

## Advanced Pattern: Handle Loading States

For production apps, you might want to handle the brief loading period when switching styles:

```jsx
import { useRef, useEffect, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';

function MapView({ mapStyle }) {
  const mapRef = useRef(null);
  const containerRef = useRef(null);
  const [isStyleLoading, setIsStyleLoading] = useState(false);

  // Initialize map once
  useEffect(() => {
    mapboxgl.accessToken = import.meta.env.VITE_MAPBOX_ACCESS_TOKEN;

    mapRef.current = new mapboxgl.Map({
      container: containerRef.current,
      style: mapStyle,
      center: [-122.4194, 37.7749],
      zoom: 12
    });

    // Listen for style load events
    mapRef.current.on('styledata', () => {
      setIsStyleLoading(false);
    });

    return () => mapRef.current.remove();
  }, []);

  // Handle style changes
  useEffect(() => {
    if (mapRef.current && mapRef.current.isStyleLoaded()) {
      setIsStyleLoading(true);
      mapRef.current.setStyle(mapStyle);
    }
  }, [mapStyle]);

  return (
    <div style={{ position: 'relative', height: '100vh' }}>
      <div ref={containerRef} style={{ height: '100%' }} />
      {isStyleLoading && (
        <div style={{
          position: 'absolute',
          top: 10,
          left: 10,
          background: 'rgba(0,0,0,0.7)',
          color: 'white',
          padding: '8px 12px',
          borderRadius: 4,
          fontSize: 14
        }}>
          Loading style...
        </div>
      )}
    </div>
  );
}
```

## Preserving Custom Layers and Sources

If you're adding custom data (markers, layers, sources) that should persist across style changes, you'll need to re-add them after each style change:

```jsx
import { useRef, useEffect, useCallback } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';

function MapView({ mapStyle, markers = [] }) {
  const mapRef = useRef(null);
  const containerRef = useRef(null);
  const markersRef = useRef([]);

  // Function to add markers
  const addMarkers = useCallback(() => {
    // Clear existing markers
    markersRef.current.forEach(marker => marker.remove());
    markersRef.current = [];

    // Add new markers
    markers.forEach(markerData => {
      const marker = new mapboxgl.Marker()
        .setLngLat([markerData.lng, markerData.lat])
        .addTo(mapRef.current);

      markersRef.current.push(marker);
    });
  }, [markers]);

  // Initialize map once
  useEffect(() => {
    mapboxgl.accessToken = import.meta.env.VITE_MAPBOX_ACCESS_TOKEN;

    mapRef.current = new mapboxgl.Map({
      container: containerRef.current,
      style: mapStyle,
      center: [-122.4194, 37.7749],
      zoom: 12
    });

    mapRef.current.on('load', () => {
      addMarkers();
    });

    return () => {
      markersRef.current.forEach(marker => marker.remove());
      mapRef.current.remove();
    };
  }, []);

  // Handle style changes
  useEffect(() => {
    if (mapRef.current && mapRef.current.isStyleLoaded()) {
      mapRef.current.setStyle(mapStyle);

      // Re-add markers after style loads
      mapRef.current.once('styledata', () => {
        addMarkers();
      });
    }
  }, [mapStyle, addMarkers]);

  return <div ref={containerRef} style={{ height: '100vh' }} />;
}
```

**Why this works:**

- **Smooth transitions**: `setStyle()` preserves viewport position and zoom level
- **No flash**: Same map instance continues rendering
- **Performance**: Only style assets are reloaded, not the entire WebGL context
- **Predictable**: Map state (position, zoom, pitch, bearing) is maintained

This is the standard pattern used in production Mapbox applications for dynamic style switching.

